class Solution {
    private int[] first,second,memo;
    private int dfs(int mask){
        if(mask==(1<<first.length)-1)return 0;
        if(memo[mask]!=-1)return memo[mask];
        int index=Integer.bitCount(mask),best=Integer.MAX_VALUE;
        for(int j=0;j<second.length;j++)if((mask&(1<<j))==0)best=Math.min(best,(first[index]^second[j])+dfs(mask|1<<j));
        return memo[mask]=best;
    }
    public int minimumXORSum(int[] nums1,int[] nums2){
        first=nums1;
        second=nums2;
        memo=new int[1<<nums1.length];
        Arrays.fill(memo,-1);
        return dfs(0);
    }
}

